-- Consumer source views: the uploaded 'Consumer' sheet (automn.stg_consumer) joined to the account view
-- wip.VwConsumerSubmissionAccountSegment. Run 00_functions.sql and 01_reference.sql first.
-- Portable source (2026-11-02): tools/build_views.py generates the Postgres / MySQL copies from this file, so write only
-- what it translates correctly: CONCAT (never '...' + ...), automn.fn_amount / fn_percent / fn_int (never TRY_CAST),
-- joins to automn.vw_ref_label / vw_ref_code for labels and codes (never a function), and CAST source-view values to
-- VARCHAR before text functions. The build refuses the forbidden forms. Run in rarfinmisdb in SSMS / Azure Data Studio
-- (GO separates batches); safe to run again (CREATE OR ALTER). A change here needs no app redeployment.
--
-- What the app expects (submissions/adapters/views.py): one view per canonical entity, automn.vw_consumer_<entity>,
-- returning the entity's columns by name with canonical values, plus load_id (the upload), which the app filters on.
-- vw_consumer_account also returns as_of_date (the source view's TransactionDate), filtered on the request's date.
-- A column a view does not return is NULL.
-- Check after a change (read-only):  python -m submissions.adapters.views CONSUMER --as-of 2026-10-28 --load-id <n>
--
-- Rules (user decisions):
--   - Account (TL) details stay at transaction-date level: one row per account per TransactionDate in the source view.
--   - Staging is append only: every upload adds its rows. An account's demographics (borrowers, IDs, phones, e-mails,
--     addresses, and the workbook's account fields) are its rows in the NEWEST successfully loaded upload that has it
--     (input_load.status = 'LOADED'), whichever request that upload belongs to.
--   - A request reports the accounts in its own upload (load_id), with those newest demographics. View accounts never
--     uploaded are ignored. An upload account missing from the view for the date is stopped by ACCOUNT_NOT_IN_VIEW.
--   - Where the view and the workbook both have a field, the view wins (the account / TL fields).
--   - One borrower per workbook row: party_key = <account number>-<Excel row> (the row in the newest upload).
--   - '(Name)' columns hold labels -> join automn.vw_ref_label; code columns -> join automn.vw_ref_code.
CREATE OR REPLACE VIEW automn.vw_consumer_stg_latest AS
SELECT
  x.*
FROM (
  SELECT
    s.*,
    l.loaded_at,
    MAX(s.load_id) OVER (PARTITION BY s.curr_new_account_no) AS latest_load_id
  FROM automn.stg_consumer AS s
  JOIN automn.input_load AS l
    ON l.load_id = s.load_id AND l.status = 'LOADED'
) AS x
WHERE
  x.load_id = x.latest_load_id;

-- Which accounts each upload has: the request's load_id selects its accounts; their data comes from the newest upload.
-- Columns: load_id (the request's upload), then the newest rows of that account: source_load_id / source_loaded_at
-- (the upload they came from, timestamp from automn.input_load) and the sheet's columns.
CREATE OR REPLACE VIEW automn.vw_consumer_borrower AS
SELECT
  u.load_id,
  s.*
FROM (
  SELECT DISTINCT
    load_id,
    curr_new_account_no AS upload_account_no
  FROM automn.stg_consumer
) AS u
JOIN (
  SELECT
    t.load_id AS source_load_id,
    t.loaded_at AS source_loaded_at,
    t.curr_new_account_no,
    t.source_row,
    t.consumer_name,
    t.date_of_birth,
    t.gender_label,
    t.occupation_code_label,
    t.income,
    t.net_gross_income_indicator,
    t.monthly_annual_income_indicator,
    t.ownership_indicator_label,
    t.income_tax_id_number,
    t.passport_number,
    t.passport_issue_date,
    t.passport_expiry_date,
    t.voter_id_number,
    t.driving_license_number,
    t.driving_license_issue_date,
    t.driving_license_expiry_date,
    t.ration_card_number,
    t.universal_id_number,
    t.ckyc,
    t.g_ram_g,
    t.telephone_no_mobile,
    t.telephone_no_residence,
    t.telephone_no_office,
    t.extension_office,
    t.telephone_no_other,
    t.extension_other,
    t.email_id_1,
    t.email_id_2,
    t.address_line_1,
    t.state_code_1_label,
    t.pin_code_1,
    t.address_category_1_label,
    t.residence_code_1_label,
    t.address_line_2,
    t.state_code_2_label,
    t.pin_code_2,
    t.address_category_2_label,
    t.residence_code_2_label,
    t.account_type,
    t.suit_filed_wilful_default_label,
    t.value_of_collateral,
    t.type_of_collateral_label,
    t.payment_frequency_label,
    t.actual_payment_amt,
    t.old_mbr_code,
    t.old_mbr_short_name,
    t.old_acc_no,
    t.old_acc_type,
    t.old_ownership_indicator,
    ROW_NUMBER() OVER (PARTITION BY t.curr_new_account_no ORDER BY t.source_row) AS rn
  FROM automn.vw_consumer_stg_latest AS t
) AS s
  ON s.curr_new_account_no = u.upload_account_no;

-- ---------------------------------------------------------------- the account (TL): the view for the date; fields
-- the view does not have come from the account's first row in its newest upload
CREATE OR REPLACE VIEW automn.vw_consumer_account AS
SELECT
  s.load_id,
  s.source_load_id,
  s.source_loaded_at,
  v.TransactionDate AS as_of_date,
  v.AccountNumber AS account_key,
  v.AccountNumber AS account_number,
  COALESCE(c_type.code, NULLIF(LTRIM(RTRIM(s.account_type)), '')) AS account_type,
  automn.fn_date(CAST(v.TL_DateDisbursed AS CHAR(40))) AS date_opened,
  automn.fn_date(CAST(v.TL_DateofLastPayment AS CHAR(40))) AS date_last_payment,
  automn.fn_date(CAST(v.TL_DateClosed AS CHAR(40))) AS date_closed,
  automn.fn_date(CAST(v.TL_DateReported AS CHAR(40))) AS date_reported,
  v.TL_SanctionedAmt AS high_credit_amount,
  v.TL_CurrentBalance AS current_balance,
  v.TL_AmtOverdue AS amount_overdue,
  v.TL_NoofDaysPastDue AS days_past_due,
  COALESCE(l_suit.code, NULLIF(LTRIM(RTRIM(s.suit_filed_wilful_default_label)), '')) AS suit_filed_status,
  COALESCE(c_status.code, v.status_code) AS credit_facility_status,
  COALESCE(c_asset.code, v.asset_code) AS asset_classification,
  automn.fn_amount(s.value_of_collateral) AS collateral_value,
  COALESCE(l_coll.code, NULLIF(LTRIM(RTRIM(s.type_of_collateral_label)), '')) AS collateral_type,
  v.TL_CreditLimit AS credit_limit,
  v.TL_CashLimit AS cash_limit,
  v.TL_RateofInterest AS rate_of_interest,
  v.TL_RepaymentTenure AS repayment_tenure,
  v.TL_EMIAmount AS emi_amount,
  v.TL_WrittenoffAmountTotal AS written_off_total,
  v.TL_WrittenOffPrincipalAmount AS written_off_principal,
  v.TL_SettlementAmt AS settlement_amount,
  COALESCE(l_freq.code, NULLIF(LTRIM(RTRIM(s.payment_frequency_label)), '')) AS payment_frequency,
  COALESCE(v.TL_ActualPaymentAmt, automn.fn_amount(s.actual_payment_amt)) AS actual_payment_amount,
  s.old_mbr_code AS old_member_code,
  s.old_mbr_short_name AS old_member_short_name,
  s.old_acc_no AS old_account_number,
  COALESCE(c_oldtype.code, NULLIF(LTRIM(RTRIM(s.old_acc_type)), '')) AS old_account_type,
  COALESCE(c_oldown.code, NULLIF(LTRIM(RTRIM(s.old_ownership_indicator)), '')) AS old_ownership_indicator
FROM (
  SELECT
    x.*,
    CASE
      WHEN NOT x.TL_CreditFacilityStatus IS NULL
      THEN RIGHT(
        CAST(CONCAT(COALESCE('0', ''), COALESCE(CAST(x.TL_CreditFacilityStatus AS CHAR(3)), '')) AS CHAR),
        2
      )
    END AS status_code,
    NULLIF(LTRIM(RTRIM(CAST(x.AssetClassification AS CHAR(40)))), '') AS asset_code
  FROM wip.VwConsumerSubmissionAccountSegment AS x
) AS v
JOIN automn.vw_consumer_borrower AS s
  ON s.curr_new_account_no = v.AccountNumber AND s.rn = 1
LEFT JOIN automn.vw_ref_code AS c_type
  ON c_type.submission_type = 'CONSUMER'
  AND c_type.code_list = 'account_type'
  AND c_type.code_key = UPPER(LTRIM(RTRIM(s.account_type)))
LEFT JOIN automn.vw_ref_label AS l_suit
  ON l_suit.submission_type = 'CONSUMER'
  AND l_suit.code_list = 'suit_filed_status'
  AND l_suit.label_key = UPPER(LTRIM(RTRIM(s.suit_filed_wilful_default_label)))
LEFT JOIN automn.vw_ref_code AS c_status
  ON c_status.submission_type = 'CONSUMER'
  AND c_status.code_list = 'credit_facility_status'
  AND c_status.code_key = v.status_code
LEFT JOIN automn.vw_ref_code AS c_asset
  ON c_asset.submission_type = 'CONSUMER'
  AND c_asset.code_list = 'asset_classification'
  AND c_asset.code_key = UPPER(v.asset_code)
LEFT JOIN automn.vw_ref_label AS l_coll
  ON l_coll.submission_type = 'CONSUMER'
  AND l_coll.code_list = 'collateral_type'
  AND l_coll.label_key = UPPER(LTRIM(RTRIM(s.type_of_collateral_label)))
LEFT JOIN automn.vw_ref_label AS l_freq
  ON l_freq.submission_type = 'CONSUMER'
  AND l_freq.code_list = 'payment_frequency'
  AND l_freq.label_key = UPPER(LTRIM(RTRIM(s.payment_frequency_label)))
LEFT JOIN automn.vw_ref_code AS c_oldtype
  ON c_oldtype.submission_type = 'CONSUMER'
  AND c_oldtype.code_list = 'account_type'
  AND c_oldtype.code_key = UPPER(LTRIM(RTRIM(s.old_acc_type)))
LEFT JOIN automn.vw_ref_code AS c_oldown
  ON c_oldown.submission_type = 'CONSUMER'
  AND c_oldown.code_list = 'ownership_indicator'
  AND c_oldown.code_key = UPPER(LTRIM(RTRIM(s.old_ownership_indicator)));

-- ---------------------------------------------------------------- borrowers and their IDs, phones, e-mails, addresses:
-- one borrower per row of the account's newest upload. No as_of_date and no join to the source view (it has one row
-- per account per date): the date is applied once, in vw_consumer_account; borrowers link to accounts through
-- vw_consumer_account_holder.
CREATE OR REPLACE VIEW automn.vw_consumer_party AS
SELECT
  s.load_id,
  s.source_load_id,
  s.source_loaded_at,
  CONCAT(COALESCE(s.curr_new_account_no, ''), COALESCE('-', ''), COALESCE(s.source_row, '')) AS party_key,
  s.consumer_name AS full_name,
  automn.fn_date(s.date_of_birth) AS birth_date,
  COALESCE(l_gender.code, NULLIF(LTRIM(RTRIM(s.gender_label)), '')) AS gender,
  COALESCE(l_occ.code, NULLIF(LTRIM(RTRIM(s.occupation_code_label)), '')) AS occupation,
  automn.fn_amount(s.income) AS income,
  COALESCE(c_basis.code, NULLIF(LTRIM(RTRIM(s.net_gross_income_indicator)), '')) AS income_basis,
  COALESCE(c_period.code, NULLIF(LTRIM(RTRIM(s.monthly_annual_income_indicator)), '')) AS income_period
FROM automn.vw_consumer_borrower AS s
LEFT JOIN automn.vw_ref_label AS l_gender
  ON l_gender.submission_type = 'CONSUMER'
  AND l_gender.code_list = 'gender'
  AND l_gender.label_key = UPPER(LTRIM(RTRIM(s.gender_label)))
LEFT JOIN automn.vw_ref_label AS l_occ
  ON l_occ.submission_type = 'CONSUMER'
  AND l_occ.code_list = 'occupation'
  AND l_occ.label_key = UPPER(LTRIM(RTRIM(s.occupation_code_label)))
LEFT JOIN automn.vw_ref_code AS c_basis
  ON c_basis.submission_type = 'CONSUMER'
  AND c_basis.code_list = 'income_basis'
  AND c_basis.code_key = UPPER(LTRIM(RTRIM(s.net_gross_income_indicator)))
LEFT JOIN automn.vw_ref_code AS c_period
  ON c_period.submission_type = 'CONSUMER'
  AND c_period.code_list = 'income_period'
  AND c_period.code_key = UPPER(LTRIM(RTRIM(s.monthly_annual_income_indicator)));

CREATE OR REPLACE VIEW automn.vw_consumer_account_holder AS
SELECT
  s.load_id,
  s.curr_new_account_no AS account_key,
  CONCAT(COALESCE(s.curr_new_account_no, ''), COALESCE('-', ''), COALESCE(s.source_row, '')) AS party_key,
  COALESCE(l_own.code, NULLIF(LTRIM(RTRIM(s.ownership_indicator_label)), '')) AS ownership_indicator
FROM automn.vw_consumer_borrower AS s
LEFT JOIN automn.vw_ref_label AS l_own
  ON l_own.submission_type = 'CONSUMER'
  AND l_own.code_list = 'ownership_indicator'
  AND l_own.label_key = UPPER(LTRIM(RTRIM(s.ownership_indicator_label)));

-- ---------------------------------------------------------------- identity documents: one row per number present
CREATE OR REPLACE VIEW automn.vw_consumer_party_identifier AS
SELECT
  s.load_id,
  CONCAT(COALESCE(s.curr_new_account_no, ''), COALESCE('-', ''), COALESCE(s.source_row, '')) AS party_key,
  d.id_type,
  d.id_number,
  d.issue_date,
  d.expiry_date
FROM automn.vw_consumer_borrower AS s CROSS JOIN LATERAL (
  (
    SELECT
      'PAN',
      s.income_tax_id_number,
      CAST(NULL AS DATE),
      CAST(NULL AS DATE)
    UNION ALL
    SELECT
      'PASSPORT',
      s.passport_number,
      automn.fn_date(s.passport_issue_date),
      automn.fn_date(s.passport_expiry_date)
    UNION ALL
    SELECT
      'VOTER_ID',
      s.voter_id_number,
      NULL,
      NULL
    UNION ALL
    SELECT
      'DRIVING_LICENCE',
      s.driving_license_number,
      automn.fn_date(s.driving_license_issue_date),
      automn.fn_date(s.driving_license_expiry_date)
    UNION ALL
    SELECT
      'RATION_CARD',
      s.ration_card_number,
      NULL,
      NULL
    UNION ALL
    SELECT
      'AADHAAR',
      s.universal_id_number,
      NULL,
      NULL
    UNION ALL
    SELECT
      'CKYC',
      s.ckyc,
      NULL,
      NULL
    UNION ALL
    SELECT
      'G_RAM_G',
      s.g_ram_g,
      NULL,
      NULL
  )
) AS d(id_type, id_number, issue_date, expiry_date)
WHERE
  NOT NULLIF(LTRIM(RTRIM(d.id_number)), '') IS NULL;

-- ---------------------------------------------------------------- phones and e-mails: one row per value present
CREATE OR REPLACE VIEW automn.vw_consumer_party_phone AS
SELECT
  s.load_id,
  CONCAT(COALESCE(s.curr_new_account_no, ''), COALESCE('-', ''), COALESCE(s.source_row, '')) AS party_key,
  p.phone_number,
  p.extension,
  p.phone_type,
  p.priority
FROM automn.vw_consumer_borrower AS s CROSS JOIN LATERAL (
  (
    SELECT
      s.telephone_no_mobile,
      CAST(NULL AS VARCHAR(20)),
      'MOBILE',
      1
    UNION ALL
    SELECT
      s.telephone_no_residence,
      NULL,
      'HOME',
      2
    UNION ALL
    SELECT
      s.telephone_no_office,
      s.extension_office,
      'OFFICE',
      3
    UNION ALL
    SELECT
      s.telephone_no_other,
      s.extension_other,
      'NOT_CLASSIFIED',
      4
  )
) AS p(phone_number, extension, phone_type, priority)
WHERE
  NOT NULLIF(LTRIM(RTRIM(p.phone_number)), '') IS NULL;

CREATE OR REPLACE VIEW automn.vw_consumer_party_email AS
SELECT
  s.load_id,
  CONCAT(COALESCE(s.curr_new_account_no, ''), COALESCE('-', ''), COALESCE(s.source_row, '')) AS party_key,
  e.email,
  e.priority
FROM automn.vw_consumer_borrower AS s CROSS JOIN LATERAL (
  (
    SELECT
      s.email_id_1,
      1
    UNION ALL
    SELECT
      s.email_id_2,
      2
  )
) AS e(email, priority)
WHERE
  NOT NULLIF(LTRIM(RTRIM(e.email)), '') IS NULL;

-- ---------------------------------------------------------------- addresses: the sheet's two address slots
CREATE OR REPLACE VIEW automn.vw_consumer_party_address AS
SELECT
  s.load_id,
  CONCAT(COALESCE(s.curr_new_account_no, ''), COALESCE('-', ''), COALESCE(s.source_row, '')) AS party_key,
  a.address_line_1,
  COALESCE(l_state.code, NULLIF(LTRIM(RTRIM(a.state_label)), '')) AS state_code,
  a.pin_code,
  COALESCE(l_cat.code, NULLIF(LTRIM(RTRIM(a.category_label)), '')) AS address_category,
  COALESCE(l_res.code, NULLIF(LTRIM(RTRIM(a.residence_label)), '')) AS residence_code,
  a.priority
FROM automn.vw_consumer_borrower AS s CROSS JOIN LATERAL (
  (
    SELECT
      s.address_line_1,
      s.state_code_1_label,
      s.pin_code_1,
      s.address_category_1_label,
      s.residence_code_1_label,
      1
    UNION ALL
    SELECT
      s.address_line_2,
      s.state_code_2_label,
      s.pin_code_2,
      s.address_category_2_label,
      s.residence_code_2_label,
      2
  )
) AS a(address_line_1, state_label, pin_code, category_label, residence_label, priority)
LEFT JOIN automn.vw_ref_label AS l_state
  ON l_state.submission_type = 'CONSUMER'
  AND l_state.code_list = 'state_code'
  AND l_state.label_key = UPPER(LTRIM(RTRIM(a.state_label)))
LEFT JOIN automn.vw_ref_label AS l_cat
  ON l_cat.submission_type = 'CONSUMER'
  AND l_cat.code_list = 'address_category'
  AND l_cat.label_key = UPPER(LTRIM(RTRIM(a.category_label)))
LEFT JOIN automn.vw_ref_label AS l_res
  ON l_res.submission_type = 'CONSUMER'
  AND l_res.code_list = 'residence_code'
  AND l_res.label_key = UPPER(LTRIM(RTRIM(a.residence_label)))
WHERE
  NOT NULLIF(LTRIM(RTRIM(a.address_line_1)), '') IS NULL;
